package com.payroll.service; import com.payroll.model.AuditLog; import com.payroll.repository.AuditLogRepository; import org.springframework.stereotype.Service; import org.springframework.data.domain.Sort; import java.util.*; @Service public class AuditService { private final AuditLogRepository repo; public AuditService(AuditLogRepository r){repo=r;} public void record(String u,String a,String e,String id,String d){repo.save(new AuditLog(u,a,e,id,d));} public List<AuditLog> all(){return repo.findAll(Sort.by(Sort.Direction.DESC,"timestamp"));} }